//! Native Matching RPC service integration.
//!
//! This module is intentionally the boundary between transport and the native
//! engine. Runtime providers must be explicit: in particular, startup,
//! admission/quota, domain-cache lookup, and queue ownership cannot be inferred
//! from the registry alone. The service uses the generated byte-valued model;
//! it never converts a request through the legacy UTF-8 protobuf model.

use cadence_common::go_string::GoString;
use cadence_persistence::matching_native_task_store::TaskListKeyBytes;
use cadence_proto::native::{self as n, NativeMatchingApi};
use tonic::{Request, Response, Status};

use crate::matching_engine_native::{
    DecisionAddContext, NativeControlContext, NativeMatchingEngine, NativePollContext,
    NativeQueryContext,
};

/// Mandatory host callbacks used by the native handler. There are no
/// permissive defaults: the runtime must provide Go-equivalent lifecycle,
/// admission, domain and ownership checks before the engine is entered.
pub trait NativeMatchingIntegration: DecisionAddContext + NativePollContext
    + NativeQueryContext + NativeControlContext + Send + Sync + 'static
{
    fn check_started(&self) -> Result<(), Status>;
    fn admit(&self, method: &'static str) -> Result<(), Status>;
    fn record_request(&self, method: &'static str);
    fn record_failure(&self, method: &'static str, status: &Status);
    fn check_owned(&self, key: &TaskListKeyBytes) -> Result<(), Status>;
    fn domain_for_name(&self, name: &GoString) -> Result<uuid::Uuid, Status>;
}

/// A native Matching service over an already constructed native engine.
///
/// Construction must use the runtime's real domain cache, quota/admission,
/// membership ownership, metrics, and poll registration providers through
/// `NativeMatchingIntegration`; a no-op provider is not a supported runtime.
pub struct NativeMatchingService<C> {
    pub engine: NativeMatchingEngine,
    pub integration: C,
}

impl<C> NativeMatchingService<C> {
    pub fn new(engine: NativeMatchingEngine, integration: C) -> Self {
        Self { engine, integration }
    }

    fn enter(&self, method: &'static str) -> Result<(), Status>
    where
        C: NativeMatchingIntegration,
    {
        self.integration.check_started()?;
        self.integration.admit(method)?;
        self.integration.record_request(method);
        Ok(())
    }

    fn finish<T>(&self, method: &'static str, result: Result<T, Status>) -> Result<T, Status>
    where
        C: NativeMatchingIntegration,
    {
        if let Err(ref status) = result {
            self.integration.record_failure(method, status);
        }
        result
    }

    fn deadline<T>(request: &Request<T>) -> Option<tokio::time::Instant> {
        crate::matching_sync::request_deadline(request)
    }
}

// The concrete RPC implementation is supplied in the next integration
// change: the generated NativeMatchingApi has a descriptor-defined method
// set, and its inputs/outputs are generated from the repository's upstream
// descriptor. Keeping this implementation explicit prevents trait defaults
// from accidentally advertising RPCs which have no handler semantics.
